const fs=require('fs'),path=require('path'),assert=require('node:assert/strict'),{JSDOM}=require('jsdom');
(async()=>{const base=path.resolve(__dirname,'../students'),dom=new JSDOM(fs.readFileSync(base+'/index.html','utf8'),{url:'https://example.test/students/#chapter-14',runScripts:'outside-only'}),w=dom.window;await new Promise(r=>w.addEventListener('load',r));for(const m of fs.readFileSync(base+'/index.html','utf8').matchAll(/src="([^"?]+\.js)/g))w.eval(fs.readFileSync(base+'/'+m[1],'utf8'));let checks=0;function ok(v,s){assert.ok(v,s);checks++}for(const c of w.MT_STUDY.chapters){w.location.hash='chapter-'+c.number;w.dispatchEvent(new w.Event('hashchange'));ok(w.document.getElementById('chapter-filter').value===String(c.number),'Chapter selected from deep link '+c.number);const count=w.document.getElementById('formula-count').textContent;ok(count===c.formulaIds.length+' / 575','Chapter count matches registered families '+c.number);ok(w.document.querySelector('#formula-grid .formula-card'),'Chapter cards rendered '+c.number)}w.location.hash='formulas';w.dispatchEvent(new w.Event('hashchange'));ok(w.document.getElementById('chapter-filter').value==='All','Normal library link resets chapter filter');ok(w.document.getElementById('formula-count').textContent==='575 / 575','Full library returns');ok(w.document.getElementById('chapter-filter').options.length===17,'Exactly16 chapter options plusAll');console.log(JSON.stringify({status:'PASS',checks,scope:'jsdom full catalogue/app integration for sixteen chapter deep links and reset'}));w.close()})().catch(e=>{console.error(e);process.exit(1)});
